(6171516, 910760, 121000, '<td valign="top">love the colours, silhouette, everything, but would like to see the pic without the distraction in the right hand corner, apart from that, epic!</td>', 'love the colours, silhouette, everything, but would like to see the pic without the distraction in the right hand corner, apart from that, epic!', '2010-09-25 08:56:02.000000', NULL, 1),
